import { Context, Effect, Layer, Schema } from 'effect'
import { RuntimeError, RuntimeMetadata } from '@hrbr/runtime-core'

export const RuntimeArtifactKind = Schema.Literals(['file', 'image', 'output'])
export type RuntimeArtifactKind = typeof RuntimeArtifactKind.Type

export const RuntimeArtifactPointer = Schema.Struct({
  key: Schema.String,
  url: Schema.String,
  kind: RuntimeArtifactKind,
  contentType: Schema.String,
  sizeBytes: Schema.Number,
  metadata: Schema.optional(RuntimeMetadata),
})
export type RuntimeArtifactPointer = typeof RuntimeArtifactPointer.Type

export interface RuntimeArtifactBinaryWrite {
  readonly kind: RuntimeArtifactKind
  readonly contentType: string
  readonly extension: string
  readonly body: Uint8Array
  readonly metadata?: RuntimeMetadata | undefined
}

export interface RuntimeArtifactBinaryWriter {
  readonly write: (
    artifact: RuntimeArtifactBinaryWrite
  ) => Promise<RuntimeArtifactPointer> | RuntimeArtifactPointer
}

export interface RuntimeArtifactStore {
  readonly write: (
    artifact: RuntimeArtifactBinaryWrite
  ) => Effect.Effect<RuntimeArtifactPointer, RuntimeError>
}

export const RuntimeArtifactStore = Context.Service<RuntimeArtifactStore>(
  '@hrbr/runtime-artifacts/RuntimeArtifactStore'
)

export const RuntimeArtifactStoreLive = (writer: RuntimeArtifactBinaryWriter) =>
  Layer.succeed(RuntimeArtifactStore, {
    write: (artifact) =>
      Effect.tryPromise({
        try: async () => writer.write(artifact),
        catch: (cause) =>
          new RuntimeError('artifact', 'Runtime artifact write failed', {
            contentType: artifact.contentType,
            kind: artifact.kind,
            cause,
          }),
      }),
  })

export const RUNTIME_DATA_URI_IMAGE_RE = /^data:(image\/[a-z+]+);base64,([A-Za-z0-9+/=]+)$/
export const RUNTIME_DATA_URI_MIN_BASE64_LENGTH = 1024

const BASE64_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
const BASE64_LOOKUP: Record<string, number> = Object.fromEntries(
  [...BASE64_CHARS].map((char, index) => [char, index])
)

export function decodeRuntimeBase64(value: string): Uint8Array {
  const clean = value.replace(/\s/g, '')
  if (clean.length % 4 === 1) throw new Error('Invalid base64 length')
  const bytes: number[] = []
  for (let index = 0; index < clean.length; index += 4) {
    const chunk = clean.slice(index, index + 4)
    const a = BASE64_LOOKUP[chunk[0] ?? '']
    const b = BASE64_LOOKUP[chunk[1] ?? '']
    const c = chunk[2] === '=' ? 0 : BASE64_LOOKUP[chunk[2] ?? '']
    const d = chunk[3] === '=' ? 0 : BASE64_LOOKUP[chunk[3] ?? '']
    if (a === undefined || b === undefined || c === undefined || d === undefined) {
      throw new Error('Invalid base64 character')
    }
    const triple = (a << 18) | (b << 12) | (c << 6) | d
    bytes.push((triple >> 16) & 0xff)
    if (chunk[2] !== '=') bytes.push((triple >> 8) & 0xff)
    if (chunk[3] !== '=') bytes.push(triple & 0xff)
  }
  return Uint8Array.from(bytes)
}

export function runtimeArtifactExtensionFromContentType(contentType: string): string {
  return contentType.split('/')[1]?.replace('+xml', '.svg') ?? 'png'
}

export interface RuntimeArtifactExtractionResult {
  readonly cleaned: unknown
  readonly artifacts: ReadonlyArray<RuntimeArtifactPointer>
}

export interface RuntimeArtifactExtractionOptions {
  readonly writer: RuntimeArtifactBinaryWriter
  readonly minBase64Length?: number | undefined
}

export async function extractRuntimeArtifactsFromValue(
  value: unknown,
  options: RuntimeArtifactExtractionOptions
): Promise<RuntimeArtifactExtractionResult> {
  const artifacts: RuntimeArtifactPointer[] = []
  const minBase64Length = options.minBase64Length ?? RUNTIME_DATA_URI_MIN_BASE64_LENGTH

  async function walk(node: unknown): Promise<unknown> {
    if (typeof node === 'string') {
      const match = node.match(RUNTIME_DATA_URI_IMAGE_RE)
      if (match && match[2]!.length > minBase64Length) {
        const contentType = match[1]!
        const body = decodeRuntimeBase64(match[2]!)
        const pointer = await options.writer.write({
          kind: 'image',
          contentType,
          extension: runtimeArtifactExtensionFromContentType(contentType),
          body,
        })
        artifacts.push(pointer)
        return pointer.url
      }
    }
    if (Array.isArray(node)) return Promise.all(node.map(walk))
    if (node && typeof node === 'object') {
      const output: Record<string, unknown> = {}
      for (const [key, child] of Object.entries(node as Record<string, unknown>)) {
        output[key] = await walk(child)
      }
      return output
    }
    return node
  }

  return {
    cleaned: await walk(value),
    artifacts,
  }
}

export interface RuntimeArtifactLimitInput {
  readonly artifactSizeBytes: number
  readonly currentRunBytes: number
  readonly maxArtifactBytes: number
  readonly maxRunBytes: number
}

export function runtimeArtifactTooLargeMessage(input: {
  readonly artifactSizeBytes: number
  readonly maxArtifactBytes: number
}): string {
  return `Artifact too large: ${(input.artifactSizeBytes / 1024 / 1024).toFixed(1)}MB exceeds ${(
    input.maxArtifactBytes /
    1024 /
    1024
  ).toFixed(0)}MB limit`
}

export function runtimeArtifactRunTotalTooLargeMessage(maxRunBytes: number): string {
  return `Run artifact total would exceed ${(maxRunBytes / 1024 / 1024).toFixed(0)}MB limit`
}

export function validateRuntimeArtifactSizeLimit(input: {
  readonly artifactSizeBytes: number
  readonly maxArtifactBytes: number
}): readonly string[] {
  if (input.artifactSizeBytes <= input.maxArtifactBytes) return []
  return [runtimeArtifactTooLargeMessage(input)]
}

export function validateRuntimeArtifactRunTotalLimit(input: {
  readonly artifactSizeBytes: number
  readonly currentRunBytes: number
  readonly maxRunBytes: number
}): readonly string[] {
  if (input.currentRunBytes + input.artifactSizeBytes <= input.maxRunBytes) return []
  return [runtimeArtifactRunTotalTooLargeMessage(input.maxRunBytes)]
}

export function validateRuntimeArtifactLimits(input: RuntimeArtifactLimitInput): readonly string[] {
  const issues: string[] = []
  issues.push(
    ...validateRuntimeArtifactSizeLimit({
      artifactSizeBytes: input.artifactSizeBytes,
      maxArtifactBytes: input.maxArtifactBytes,
    })
  )
  issues.push(
    ...validateRuntimeArtifactRunTotalLimit({
      artifactSizeBytes: input.artifactSizeBytes,
      currentRunBytes: input.currentRunBytes,
      maxRunBytes: input.maxRunBytes,
    })
  )
  return issues
}

export interface LocalRuntimeArtifactStoreSnapshot {
  readonly artifacts: ReadonlyArray<RuntimeArtifactPointer>
}

export function makeLocalRuntimeArtifactStore() {
  const artifacts: RuntimeArtifactPointer[] = []
  const layer = RuntimeArtifactStoreLive({
    write: (artifact) => {
      const pointer: RuntimeArtifactPointer = {
        key: 'local-artifact-' + String(artifacts.length + 1),
        url: 'memory://local-artifact-' + String(artifacts.length + 1),
        kind: artifact.kind,
        contentType: artifact.contentType,
        sizeBytes: artifact.body.byteLength,
        ...(artifact.metadata ? { metadata: artifact.metadata } : {}),
      }
      artifacts.push(pointer)
      return pointer
    },
  })
  return {
    layer,
    snapshot: (): LocalRuntimeArtifactStoreSnapshot => ({
      artifacts: artifacts.slice(),
    }),
  }
}
